-- Fixed27 scalar metadata lookup. No body capture, row digest or processing gate.
-- The source relation/tuple predicates preserve the existing parent namespaces;
-- caller input never selects a table/function identifier.
CREATE FUNCTION public.manual_source_personal_row_exists_v1(i jsonb,refs jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $$
DECLARE tenant text:=nullif(current_setting('app.athlete_id',true),''); q text; v text; observed boolean;
BEGIN
 IF tenant IS NULL THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_CORRUPT'; END IF;
 CASE i->>'kind'
 WHEN 'race-event' THEN v:=i->>'revision'; q:=$query$SELECT 'race-event'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.race_event WHERE athlete_id=$1 AND id::text=$2->>'sourceId' AND revision=($2->>'revision')::int AND NOT deleted$query$;
 WHEN 'plan-snapshot' THEN v:=i->>'version'; q:=$query$SELECT 'plan-snapshot'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.plan_snapshot WHERE athlete_id=$1 AND id::text=$2->>'sourceId' AND version=($2->>'version')::int$query$;
 WHEN 'nutrition-plan-version' THEN v:=i->>'versionId'; q:=$query$SELECT 'nutrition-plan'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.nutrition_plan_version WHERE athlete_id=$1 AND plan_id::text=$2->>'sourceId' AND version_id::text=$2->>'versionId'$query$;
 WHEN 'routine-schedule-version' THEN v:=i->>'versionId'; q:=$query$SELECT 'routine-schedule'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.routine_schedule_version WHERE athlete_id=$1 AND schedule_id::text=$2->>'sourceId' AND version_id::text=$2->>'versionId'$query$;
 WHEN 'routine-blueprint-version' THEN v:=i->>'versionId'; q:=$query$SELECT 'routine-blueprint'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.routine_blueprint_version WHERE athlete_id=$1 AND routine_id::text=$2->>'sourceId' AND version_id::text=$2->>'versionId'$query$;
 WHEN 'routine-occurrence' THEN v:=NULL; q:=$query$SELECT 'routine-occurrence'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.routine_occurrence WHERE athlete_id=$1 AND id::text=$2->>'sourceId'$query$;
 WHEN 'routine-run' THEN v:=i->>'revision'; q:=$query$SELECT 'routine-run'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.routine_run_revision WHERE athlete_id=$1 AND run_id::text=$2->>'sourceId' AND revision=($2->>'revision')::int$query$;
 WHEN 'session-completion' THEN v:=replace(jsonb_build_array(i->>'planVersionId',(i->>'revision')::int)::text,', ', ','); q:=$query$SELECT 'session-completion'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.session_completion_revision WHERE athlete_id=$1 AND session_id::text=$2->>'sourceId' AND revision=($2->>'revision')::int AND record_json->>'planVersionId'=$2->>'planVersionId' UNION ALL SELECT 'plan-snapshot',p.id::text,p.version::text,'parent',NULL::jsonb FROM public.plan_snapshot p WHERE p.athlete_id=$1 AND p.id::text=$2->>'planVersionId' AND EXISTS(SELECT 1 FROM jsonb_array_elements(p.draft->'sessions') s WHERE s->>'id'=$2->>'sourceId')$query$;
 WHEN 'food-definition-version' THEN v:=i->>'versionId'; q:=$query$SELECT 'food-definition'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.food_definition_version WHERE athlete_id=$1 AND food_id::text=$2->>'sourceId' AND version_id::text=$2->>'versionId'$query$;
 WHEN 'recovery-strategy-version' THEN v:=i->>'versionId'; q:=$query$SELECT 'recovery-strategy'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.recovery_strategy_version WHERE athlete_id=$1 AND strategy_id::text=$2->>'sourceId' AND version_id::text=$2->>'versionId'$query$;
 WHEN 'recovery-method-version' THEN v:=i->>'versionId'; q:=$query$SELECT 'recovery-method'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.recovery_method_version WHERE athlete_id=$1 AND method_id::text=$2->>'sourceId' AND version_id::text=$2->>'versionId'$query$;
 WHEN 'workout-template-version' THEN v:=i->>'versionId'; q:=$query$SELECT 'workout-template'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.supplementary_routine_version WHERE athlete_id=$1 AND routine_id::text=$2->>'sourceId' AND version_id::text=$2->>'versionId' UNION ALL SELECT 'supplementary-exercise',e.exercise_id::text,e.version_id::text,'target',jsonb_build_array(t.routine_version_id,t.target_set_id) FROM public.supplementary_routine_target_ref t JOIN public.supplementary_exercise_version e ON e.athlete_id=t.athlete_id AND e.version_id=t.exercise_version_id WHERE t.athlete_id=$1 AND t.routine_version_id::text=$2->>'versionId'$query$;
 WHEN 'supplementary-exercise-version' THEN v:=i->>'versionId'; q:=$query$SELECT 'supplementary-exercise'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.supplementary_exercise_version WHERE athlete_id=$1 AND exercise_id::text=$2->>'sourceId' AND version_id::text=$2->>'versionId'$query$;
 WHEN 'resource-text-version' THEN v:=i->>'versionId'; q:=$query$SELECT 'resource'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.resource_version WHERE athlete_id=$1 AND resource_id::text=$2->>'sourceId' AND version_id::text=$2->>'versionId' AND EXISTS(SELECT 1 FROM public.resource p WHERE p.athlete_id=resource_version.athlete_id AND p.id=resource_version.resource_id AND p.deleted_at IS NULL)$query$;
 WHEN 'supplementary-session-copy' THEN v:=NULL; q:=$query$SELECT 'plan-snapshot'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'parent'::text AS role, NULL::jsonb AS "membershipKey" FROM public.supplementary_session_link WHERE athlete_id=$1 AND plan_version_id::text=$2->>'sourceId' AND planned_session_id=$2->>'sessionId' UNION ALL SELECT 'supplementary-exercise',e.exercise_id::text,e.version_id::text,'target',jsonb_build_array(t.plan_version_id,t.planned_session_id,t.target_set_id) FROM public.supplementary_session_target_ref t JOIN public.supplementary_exercise_version e ON e.athlete_id=t.athlete_id AND e.version_id=t.exercise_version_id WHERE t.athlete_id=$1 AND t.plan_version_id::text=$2->>'sourceId' AND t.planned_session_id=$2->>'sessionId'$query$;
 WHEN 'manual-activity-source' THEN v:=replace(jsonb_build_array('manual',i->>'sourceRecordId',(i->>'sourceRevision')::int)::text,', ', ','); q:=$query$SELECT 'activity'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.activity_source_revision WHERE athlete_id=$1 AND source_id=$2->>'sourceRecordId' AND source_revision=($2->>'sourceRevision')::int AND EXISTS(SELECT 1 FROM public.activity_source_head h WHERE h.athlete_id=activity_source_revision.athlete_id AND h.kind=activity_source_revision.kind AND h.source_id=activity_source_revision.source_id AND h.activity_id::text=$2->>'sourceId' AND EXISTS(SELECT 1 FROM public.activity_canonical a WHERE a.athlete_id=h.athlete_id AND a.id=h.activity_id AND NOT a.deleted) AND NOT EXISTS(SELECT 1 FROM public.activity_suppression z WHERE z.athlete_id=h.athlete_id AND z.kind=h.kind AND z.source_id=h.source_id))$query$;
 WHEN 'activity-overlay' THEN v:=i->>'revision'; q:=$query$SELECT 'activity'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.activity_overlay_revision WHERE athlete_id=$1 AND activity_id::text=$2->>'sourceId' AND revision=($2->>'revision')::int$query$;
 WHEN 'activity-canonical-values' THEN v:=i->>'revision'; q:=$query$SELECT 'activity'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.activity_canonical WHERE athlete_id=$1 AND id::text=$2->>'sourceId' AND revision=($2->>'revision')::int AND NOT deleted$query$;
 WHEN 'intake-revision' THEN v:=i->>'revisionId'; q:=$query$SELECT 'intake'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.intake_entry_revision WHERE athlete_id=$1 AND intake_id::text=$2->>'sourceId' AND revision_id::text=$2->>'revisionId' AND EXISTS(SELECT 1 FROM public.intake_entry h WHERE h.athlete_id=intake_entry_revision.athlete_id AND h.id=intake_entry_revision.intake_id AND h.status='active') UNION ALL SELECT 'intake-origin',r.revision_id::text,NULL,'origin',NULL::jsonb FROM public.intake_entry_revision r JOIN public.intake_entry h ON h.athlete_id=r.athlete_id AND h.id=r.intake_id WHERE r.athlete_id=$1 AND r.intake_id::text=$2->>'sourceId' AND r.revision=1 AND r.status='active' AND h.status='active'$query$;
 WHEN 'checkin-revision' THEN v:=i->>'revision'; q:=$query$SELECT 'checkin'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.check_in_revision WHERE athlete_id=$1 AND check_in_id::text=$2->>'sourceId' AND revision=($2->>'revision')::int$query$;
 WHEN 'checklist-confirmation' THEN v:=i->>'revisionId'; q:=$query$SELECT 'checklist-confirmation'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.routine_checklist_confirmation WHERE athlete_id=$1 AND id::text=$2->>'sourceId' AND revision_id::text=$2->>'revisionId' AND run_id::text=$2->>'runId' AND step_id=$2->>'stepId' UNION ALL SELECT 'routine-run',r.id::text,NULL,'parent',NULL::jsonb FROM public.routine_run r WHERE r.athlete_id=$1 AND r.id::text=$2->>'runId'$query$;
 WHEN 'course-revision' THEN v:=replace(jsonb_build_array(i->>'revisionId',(i->>'revision')::int)::text,', ', ','); q:=$query$SELECT 'course'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.course_revision WHERE athlete_id=$1 AND course_id::text=$2->>'sourceId' AND revision_id::text=$2->>'revisionId' AND course_revision=($2->>'revision')::int UNION ALL SELECT 'activity',s.activity_id::text,NULL,'lineage',NULL::jsonb FROM public.course_revision_source s WHERE s.athlete_id=$1 AND s.course_id::text=$2->>'sourceId' AND s.course_revision=($2->>'revision')::int UNION ALL SELECT 'activity-track',s.activity_id::text,replace(jsonb_build_array(s.track_id,s.track_revision)::text,', ',','),'lineage',NULL::jsonb FROM public.course_revision_source s WHERE s.athlete_id=$1 AND s.course_id::text=$2->>'sourceId' AND s.course_revision=($2->>'revision')::int$query$;
 WHEN 'activity-track-descriptor' THEN v:=replace(jsonb_build_array(i->>'trackId',(i->>'revision')::int)::text,', ', ','); q:=$query$SELECT 'activity-track'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.activity_track_revision WHERE athlete_id=$1 AND activity_id::text=$2->>'sourceId' AND track_id::text=$2->>'trackId' AND track_revision=($2->>'revision')::int UNION ALL SELECT 'activity',a.id::text,NULL,'parent',NULL::jsonb FROM public.activity_canonical a WHERE a.athlete_id=$1 AND a.id::text=$2->>'sourceId'$query$;
 WHEN 'course-head-descriptor' THEN v:=i->>'revision'; q:=$query$SELECT 'course'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.course WHERE athlete_id=$1 AND course_id::text=$2->>'sourceId' AND head_revision=($2->>'revision')::int UNION ALL SELECT 'activity',s.activity_id::text,NULL,'lineage',NULL::jsonb FROM public.course_revision_source s WHERE s.athlete_id=$1 AND s.course_id::text=$2->>'sourceId' AND s.course_revision=($2->>'revision')::int UNION ALL SELECT 'activity-track',s.activity_id::text,replace(jsonb_build_array(s.track_id,s.track_revision)::text,', ',','),'lineage',NULL::jsonb FROM public.course_revision_source s WHERE s.athlete_id=$1 AND s.course_id::text=$2->>'sourceId' AND s.course_revision=($2->>'revision')::int$query$;
 WHEN 'gallery-descriptor' THEN v:=i->>'accessRevision'; q:=$query$SELECT 'gallery-media'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'source'::text AS role, NULL::jsonb AS "membershipKey" FROM public.gallery_media_item WHERE athlete_id=$1 AND id::text=$2->>'sourceId' AND access_revision=($2->>'accessRevision')::int AND deleted_at IS NULL$query$;
 WHEN 'routine-timer' THEN v:=replace(jsonb_build_array(i->>'stepId',(i->>'revision')::int)::text,', ', ','); q:=$query$SELECT 'routine-run'::text AS family, $2->>'sourceId' AS "sourceId", $3::text AS "versionKey", 'parent'::text AS role, NULL::jsonb AS "membershipKey" FROM public.routine_step_timer WHERE athlete_id=$1 AND run_id::text=$2->>'sourceId' AND step_id=$2->>'stepId' AND revision=($2->>'revision')::int$query$;
 WHEN 'race-timing-pin-fragment' THEN v:=NULL; q:=$query$SELECT 'nutrition-plan'::text AS family,n.plan_id::text AS "sourceId",n.version_id::text AS "versionKey",'pin_parent'::text AS role,NULL::jsonb AS "membershipKey" FROM public.nutrition_plan_version n WHERE n.athlete_id=$1 AND EXISTS(SELECT 1 FROM jsonb_array_elements($4) ref WHERE ref->>'kind'='nutrition-plan-version' AND ref->>'sourceId'=n.plan_id::text AND ref->>'versionId'=n.version_id::text) AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(n.record_json->'raceTimingPins','[]'::jsonb)) pin WHERE pin->>'eventId'=$2->>'sourceId' AND pin->>'eventRevision'=$2->>'revision' AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(n.record_json->'itemRaceTimingBindings','[]'::jsonb)) binding WHERE binding->'binding'->>'state'='captured' AND binding->'binding'->>'eventId'=pin->>'eventId' AND binding->'binding'->>'eventRevision'=pin->>'eventRevision'))$query$;
 ELSE RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_CORRUPT'; END CASE;
 EXECUTE 'SELECT EXISTS(SELECT 1 FROM ('||q||') actual WHERE role=''source'' OR ($5 IN (''routine-timer'',''supplementary-session-copy'') AND role=''parent'') OR ($5=''race-timing-pin-fragment'' AND role=''pin_parent''))' INTO observed USING tenant,i,v,refs,i->>'kind';
 RETURN observed;
END $$;
REVOKE ALL ON FUNCTION public.manual_source_personal_row_exists_v1(jsonb,jsonb) FROM PUBLIC;

-- Unregistered personal retained metadata readers. No restore/purpose credential.
-- Original source bodies, paths, locators, SQL row hashes and receipts stay private.
CREATE FUNCTION public.read_manual_race_source_personal_export_v1(byte_limit integer) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' SET DateStyle='ISO,YMD' AS $$
DECLARE
 tenant text:=public.race_manual_public_scope_v1();
 n bigint; raw_bytes bigint; chain_row record; ref_row record; suppression_row record;
 current_edges jsonb; chain_refs jsonb; event_row public.restore_suppression_event;
 chains jsonb:='[]'; refs jsonb:='[]'; parents jsonb; suppressions jsonb:='[]'; matched jsonb; result jsonb; state text;
BEGIN
 IF byte_limit IS NULL OR byte_limit NOT BETWEEN 1 AND 8388608 THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_INVALID_BOUND'; END IF;
 IF current_setting('transaction_isolation') NOT IN ('repeatable read','serializable') THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_SNAPSHOT_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(tenant,0));
 PERFORM pg_advisory_xact_lock(hashtextextended(tenant,77209));
 SELECT count(*) INTO n FROM (SELECT 1 FROM public.manual_race_evidence_v2 WHERE athlete_id=tenant LIMIT 1001) counted;
 IF n>1000 THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_TOO_LARGE'; END IF;
 -- Count and scalar metadata bytes precede any body/array aggregation. Per-event
 -- matching reserves every ordinal in that chain before computing exact matches.
 SELECT coalesce((SELECT sum(coalesce(octet_length((payload->'payload'->'preparation')::text),0)+512) FROM public.manual_race_evidence_v2 WHERE athlete_id=tenant),0)
 +coalesce((SELECT sum(octet_length(identity::text)+octet_length(copied_locations::text)+512) FROM public.manual_race_chain_source_ref_v2 WHERE athlete_id=tenant),0)
 +coalesce((SELECT sum(octet_length(edge::text)+512) FROM public.manual_race_chain_lifecycle_edge_v2 WHERE athlete_id=tenant),0)
 +coalesce((SELECT sum(512+12*(SELECT count(*) FROM public.manual_race_chain_source_ref_v2 r WHERE r.athlete_id=s.athlete_id AND r.evidence_id=s.evidence_id)) FROM public.manual_race_chain_suppression_v2 s WHERE s.athlete_id=tenant),0)+1024 INTO raw_bytes;
 IF raw_bytes>byte_limit THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_TOO_LARGE'; END IF;
 FOR chain_row IN SELECT e.* FROM public.manual_race_evidence_v2 e WHERE e.athlete_id=tenant ORDER BY e.created_at,e.id LOOP
  IF NOT EXISTS(SELECT 1 FROM public.manual_race_decision_v2 d JOIN public.manual_race_proposal_v2 p ON p.athlete_id=d.athlete_id AND p.evidence_id=d.evidence_id AND p.decision_id=d.id WHERE d.athlete_id=tenant AND d.evidence_id=chain_row.id AND d.id=chain_row.decision_id AND p.id=chain_row.proposal_id)
  THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_CORRUPT'; END IF;
  IF chain_row.payload IS NULL AND NOT EXISTS(SELECT 1 FROM public.manual_race_chain_suppression_v2 s JOIN public.restore_suppression_event e ON e.athlete_id=s.athlete_id AND e.event_id=s.event_id WHERE s.athlete_id=tenant AND s.evidence_id=chain_row.id AND s.event_id=chain_row.purged_event_id AND s.occurred_at=chain_row.purged_at AND s.original_payload_sql_digest=chain_row.original_payload_sql_digest AND e.occurred_at=s.occurred_at)
  THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_CORRUPT'; END IF;
  IF chain_row.payload IS NOT NULL AND (chain_row.purged_event_id IS NOT NULL OR chain_row.purged_at IS NOT NULL) THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_CORRUPT'; END IF;
  SELECT jsonb_agg(r.identity ORDER BY r.ordinal) INTO chain_refs FROM public.manual_race_chain_source_ref_v2 r WHERE r.athlete_id=tenant AND r.evidence_id=chain_row.id;
  IF chain_refs IS NULL OR jsonb_array_length(chain_refs) NOT BETWEEN 1 AND 5000 OR (SELECT max(ordinal) FROM public.manual_race_chain_source_ref_v2 WHERE athlete_id=tenant AND evidence_id=chain_row.id)<>jsonb_array_length(chain_refs) THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_CORRUPT'; END IF;

  chains:=chains||jsonb_build_array(jsonb_build_object('evidenceId',chain_row.id,'decisionId',chain_row.decision_id,'proposalId',chain_row.proposal_id,
   'preparation',CASE WHEN chain_row.payload IS NULL THEN NULL ELSE chain_row.payload->'payload'->'preparation' END,
   'savedRefCount',jsonb_array_length(chain_refs),
   'savedParentCount',(SELECT count(*) FROM public.manual_race_chain_lifecycle_edge_v2 WHERE athlete_id=tenant AND evidence_id=chain_row.id),
   'savedSuppressionCount',(SELECT count(*) FROM public.manual_race_chain_suppression_v2 WHERE athlete_id=tenant AND evidence_id=chain_row.id),
   'body',CASE WHEN chain_row.payload IS NULL THEN jsonb_build_object('state','purged','eventId',chain_row.purged_event_id,'occurredAt',to_char(chain_row.purged_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) ELSE jsonb_build_object('state','present') END));
  FOR ref_row IN SELECT r.* FROM public.manual_race_chain_source_ref_v2 r WHERE r.athlete_id=tenant AND r.evidence_id=chain_row.id ORDER BY r.ordinal LOOP
   state:=CASE WHEN public.manual_source_personal_row_exists_v1(ref_row.identity,chain_refs) THEN 'present' ELSE 'unavailable' END;
   IF EXISTS(SELECT 1 FROM public.manual_race_chain_suppression_v2 s JOIN public.restore_suppression_event e ON e.athlete_id=s.athlete_id AND e.event_id=s.event_id JOIN public.manual_race_chain_lifecycle_edge_v2 l ON l.athlete_id=s.athlete_id AND l.evidence_id=s.evidence_id AND l.ordinal=ref_row.ordinal WHERE s.athlete_id=tenant AND s.evidence_id=chain_row.id AND s.original_payload_sql_digest=chain_row.original_payload_sql_digest AND e.occurred_at=s.occurred_at AND public.manual_race_v2_event_matches_ref(e,ref_row.identity,l.edge)) THEN state:='deleted'; END IF;
   refs:=refs||jsonb_build_array(jsonb_build_object('evidenceId',chain_row.id,'ordinal',ref_row.ordinal,'identity',ref_row.identity,'dtoDigest',ref_row.dto_digest,'copiedLocations',ref_row.copied_locations,
    'trainingAggregateId',CASE WHEN ref_row.identity->>'kind'='plan-snapshot' THEN (SELECT a.aggregate_id FROM public.plan_snapshot_aggregate a WHERE a.athlete_id=tenant AND a.version_id::text=ref_row.identity->>'sourceId') ELSE NULL END,
    'sourceKind',CASE WHEN ref_row.identity->>'kind'='manual-activity-source' THEN (SELECT x.value->'key'->>0 FROM jsonb_array_elements(ref_row.sql_relations) x(value) WHERE x.value->>'relation'='activity_source_revision' LIMIT 1) ELSE NULL END,
    'parentCoverage',CASE WHEN EXISTS(SELECT 1 FROM public.manual_race_chain_lifecycle_edge_v2 WHERE athlete_id=tenant AND evidence_id=chain_row.id AND ordinal=ref_row.ordinal) THEN 'saved_parents' ELSE 'legacy_association_unavailable' END,
    'existence',jsonb_build_object('basis','export_snapshot','state',state),
    'location',jsonb_build_object('state','unavailable','reason',CASE WHEN chain_row.payload IS NULL THEN 'payload_purged' ELSE 'private_source_not_rendered' END)));
  END LOOP;
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('evidenceId',e.evidence_id,'ordinal',e.ordinal,'edge',e.edge) ORDER BY e.evidence_id,e.ordinal,e.edge_key),'[]') INTO parents FROM public.manual_race_chain_lifecycle_edge_v2 e WHERE e.athlete_id=tenant;
 FOR suppression_row IN SELECT s.* FROM public.manual_race_chain_suppression_v2 s WHERE s.athlete_id=tenant ORDER BY s.evidence_id,s.occurred_at,s.event_id LOOP
  SELECT * INTO event_row FROM public.restore_suppression_event WHERE athlete_id=tenant AND event_id=suppression_row.event_id;
  IF NOT FOUND OR event_row.occurred_at IS DISTINCT FROM suppression_row.occurred_at OR NOT EXISTS(SELECT 1 FROM public.manual_race_evidence_v2 e WHERE e.athlete_id=tenant AND e.id=suppression_row.evidence_id AND e.original_payload_sql_digest=suppression_row.original_payload_sql_digest) THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_CORRUPT'; END IF;
  SELECT coalesce(jsonb_agg(o.ordinal ORDER BY o.ordinal),'[]') INTO matched FROM (SELECT DISTINCT r.ordinal FROM public.manual_race_chain_source_ref_v2 r JOIN public.manual_race_chain_lifecycle_edge_v2 l ON l.athlete_id=r.athlete_id AND l.evidence_id=r.evidence_id AND l.ordinal=r.ordinal WHERE r.athlete_id=tenant AND r.evidence_id=suppression_row.evidence_id AND public.manual_race_v2_event_matches_ref(event_row,r.identity,l.edge)) o;
  IF jsonb_array_length(matched)=0 THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_CORRUPT'; END IF;
  suppressions:=suppressions||jsonb_build_array(jsonb_build_object('evidenceId',suppression_row.evidence_id,'eventId',event_row.event_id,'occurredAt',to_char(event_row.occurred_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'recordVersion',event_row.record_version,'kind',event_row.kind,'matchedRefOrdinals',matched));
 END LOOP;
 result:=jsonb_build_object('schemaVersion',1,'chains',chains,'refs',refs,'parents',parents,'suppressions',suppressions);
 IF octet_length(result::text)>byte_limit THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_TOO_LARGE'; END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.read_manual_race_source_personal_export_v1(integer) FROM PUBLIC;

CREATE FUNCTION public.read_nutrition_disconnection_personal_export_v1(byte_limit integer) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' SET DateStyle='ISO,YMD' AS $$
DECLARE tenant text:=public.race_manual_public_scope_v1(); raw_bytes bigint; origins jsonb; lineage jsonb; result jsonb;
BEGIN
 IF byte_limit IS NULL OR byte_limit NOT BETWEEN 1 AND 8388608 THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_INVALID_BOUND'; END IF;
 IF current_setting('transaction_isolation') NOT IN ('repeatable read','serializable') THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_SNAPSHOT_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(tenant,0));
 PERFORM pg_advisory_xact_lock(hashtextextended(tenant,77209));
 SELECT coalesce((SELECT sum(octet_length(to_jsonb(item_id)::text)+512) FROM public.nutrition_race_item_disconnection WHERE athlete_id=tenant),0)+coalesce((SELECT sum(octet_length(to_jsonb(item_id)::text)+768) FROM public.nutrition_race_disconnection_lineage WHERE athlete_id=tenant),0)+1024 INTO raw_bytes;
 IF raw_bytes>byte_limit THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_TOO_LARGE'; END IF;
 IF EXISTS(SELECT 1 FROM public.nutrition_race_item_disconnection d LEFT JOIN public.nutrition_plan_version v ON v.athlete_id=d.athlete_id AND v.version_id=d.version_id LEFT JOIN public.restore_suppression_event e ON e.athlete_id=d.athlete_id AND e.event_id=d.event_id WHERE d.athlete_id=tenant AND (v.version_id IS NULL OR e.event_id IS NULL OR e.record_version<>4 OR e.kind<>'race_event_deleted' OR d.item_key<>sha256(convert_to(d.item_id,'UTF8'))))
 -- Historical lineage keeps its original ancestor even when a later deletion
 -- installs a newer direct origin on its prior version. Current-origin resolution
 -- is a write-time port; retained export validates the saved exact ancestry.
 OR EXISTS(SELECT 1 FROM public.nutrition_race_disconnection_lineage l WHERE l.athlete_id=tenant AND NOT EXISTS(
  SELECT 1 FROM public.nutrition_plan_version saved
  JOIN public.nutrition_plan_version prior ON prior.athlete_id=saved.athlete_id AND prior.plan_id=saved.plan_id AND prior.version_id=l.prior_version_id AND prior.version=l.prior_version
  JOIN public.nutrition_plan_version original ON original.athlete_id=saved.athlete_id AND original.plan_id=saved.plan_id AND original.version_id=l.origin_version_id
  JOIN public.nutrition_race_item_disconnection marker ON marker.athlete_id=original.athlete_id AND marker.version_id=original.version_id AND marker.item_key=l.item_key AND marker.item_id=l.item_id AND marker.event_id=l.origin_event_id
  JOIN public.restore_suppression_event event ON event.athlete_id=marker.athlete_id AND event.event_id=marker.event_id AND event.record_version=4 AND event.kind='race_event_deleted'
  WHERE saved.athlete_id=l.athlete_id AND saved.plan_id=l.plan_id AND saved.version_id=l.version_id AND saved.version=l.version
   AND saved.previous_version_id=prior.version_id AND l.version=l.prior_version+1 AND l.item_key=sha256(convert_to(l.item_id,'UTF8'))
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(saved.record_json->'items') item WHERE item->>'id'=l.item_id)
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(prior.record_json->'items') item WHERE item->>'id'=l.item_id)
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(original.record_json->'items') item WHERE item->>'id'=l.item_id AND item->'anchor'='{"kind":"disconnected","entity":"race"}'::jsonb)
   AND (EXISTS(SELECT 1 FROM public.nutrition_race_item_disconnection d WHERE d.athlete_id=l.athlete_id AND d.version_id=l.prior_version_id AND d.version_id=l.origin_version_id AND d.item_key=l.item_key AND d.item_id=l.item_id AND d.event_id=l.origin_event_id)
    OR EXISTS(SELECT 1 FROM public.nutrition_race_disconnection_lineage p WHERE p.athlete_id=l.athlete_id AND p.plan_id=l.plan_id AND p.version_id=l.prior_version_id AND p.version=l.prior_version AND p.item_key=l.item_key AND p.item_id=l.item_id AND p.origin_version_id=l.origin_version_id AND p.origin_event_id=l.origin_event_id))
 )) THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_CORRUPT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('planId',v.plan_id,'versionId',d.version_id,'itemId',d.item_id,'originVersionId',d.version_id,'eventId',d.event_id,'occurredAt',to_char(e.occurred_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'eventKind','race_event_deleted') ORDER BY v.plan_id,d.version_id,public.nutrition_copy_utf16_key(d.item_id)),'[]') INTO origins FROM public.nutrition_race_item_disconnection d JOIN public.nutrition_plan_version v ON v.athlete_id=d.athlete_id AND v.version_id=d.version_id JOIN public.restore_suppression_event e ON e.athlete_id=d.athlete_id AND e.event_id=d.event_id WHERE d.athlete_id=tenant;
 SELECT coalesce(jsonb_agg(jsonb_build_object('planId',l.plan_id,'versionId',l.version_id,'version',l.version,'priorVersionId',l.prior_version_id,'priorVersion',l.prior_version,'itemId',l.item_id,'originVersionId',l.origin_version_id,'eventId',l.origin_event_id,'disposition',l.disposition) ORDER BY l.plan_id,l.version,public.nutrition_copy_utf16_key(l.item_id)),'[]') INTO lineage FROM public.nutrition_race_disconnection_lineage l WHERE l.athlete_id=tenant;
 result:=jsonb_build_object('schemaVersion',1,'origins',origins,'lineage',lineage);
 IF octet_length(result::text)>byte_limit THEN RAISE EXCEPTION 'MANUAL_SOURCE_EXPORT_TOO_LARGE'; END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.read_nutrition_disconnection_personal_export_v1(integer) FROM PUBLIC;
